extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_main_scene()
	if not check("basket", basket != null, "La scena basket.tscn deve caricarsi correttamente"):
		return
	if not check("has_func", has_function(basket, "spawn_rock_row"), "Il cesto deve contenere la funzione spawn_rock_row"):
		return
	var rocks: Array[Node] = []
	for child in basket.get_children():
		if child is Sprite2D and child.get_script() != null:
			var script_path: String = child.get_script().resource_path
			if "rock.gd" in script_path:
				rocks.append(child)
	if not check("rock_count", rocks.size() == 5, "Il metodo spawn_rock_row deve creare esattamente 5 rocce"):
		return
	var first_rock: Sprite2D = rocks[0] as Sprite2D
	var last_rock: Sprite2D = rocks[4] as Sprite2D
	check("positions", is_equal_approx(first_rock.position.x, 160.0) and is_equal_approx(last_rock.position.x, 960.0), "La prima roccia deve partire da X=160 e l'ultima arrivare a X=960")
